from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 7, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="t", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, created_at=None, tags=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# ── TaskQuery validation ────────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(sort="bad")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


# ── Filtering ────────────────────────────────────────────────────────────────

class TestApplyQueryFiltering:
    TASKS = [
        _task(1, "Buy milk", status=TaskStatus.PENDING, tags=[Tag("shopping")]),
        _task(2, "Write code", status=TaskStatus.DONE, tags=[Tag("dev")]),
        _task(3, "Plan trip", status=TaskStatus.PENDING,
              due_at=NOW - timedelta(days=1), tags=[Tag("travel"), Tag("shopping")]),
    ]

    def test_filter_by_status_pending(self):
        page = apply_query(self.TASKS, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_status_done(self):
        page = apply_query(self.TASKS, TaskQuery(status=TaskStatus.DONE), NOW)
        assert [t.id for t in page.items] == [2]

    def test_filter_by_tag(self):
        page = apply_query(self.TASKS, TaskQuery(tag="shopping"), NOW)
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_search(self):
        page = apply_query(self.TASKS, TaskQuery(search="milk"), NOW)
        assert [t.id for t in page.items] == [1]

    def test_search_is_case_insensitive(self):
        page = apply_query(self.TASKS, TaskQuery(search="WRITE"), NOW)
        assert [t.id for t in page.items] == [2]

    def test_filter_overdue_true(self):
        page = apply_query(self.TASKS, TaskQuery(overdue=True), NOW)
        assert [t.id for t in page.items] == [3]

    def test_filter_overdue_false(self):
        page = apply_query(self.TASKS, TaskQuery(overdue=False), NOW)
        assert {t.id for t in page.items} == {1, 2}

    def test_combined_filters(self):
        page = apply_query(
            self.TASKS,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping"),
            NOW,
        )
        assert {t.id for t in page.items} == {1, 3}


# ── Sorting ──────────────────────────────────────────────────────────────────

class TestApplyQuerySorting:
    def test_sort_by_title_asc(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_desc(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Cherry", "Banana", "Apple"]

    def test_sort_by_priority(self):
        tasks = [
            _task(1, priority=TaskPriority.LOW),
            _task(2, priority=TaskPriority.HIGH),
            _task(3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        assert priorities == [TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            _task(1, due_at=None),
            _task(2, due_at=NOW + timedelta(days=1)),
            _task(3, due_at=NOW - timedelta(days=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        ids = [t.id for t in page.items]
        # None sorts last, earliest due first
        assert ids == [3, 2, 1]

    def test_sort_by_created_at(self):
        tasks = [
            _task(1, created_at=NOW + timedelta(hours=2)),
            _task(2, created_at=NOW),
            _task(3, created_at=NOW + timedelta(hours=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]


# ── Pagination ───────────────────────────────────────────────────────────────

class TestApplyQueryPagination:
    TASKS = [_task(i, title=f"task-{i}") for i in range(1, 6)]

    def test_limit(self):
        page = apply_query(self.TASKS, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self):
        page = apply_query(self.TASKS, TaskQuery(limit=2, offset=3), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self):
        page = apply_query(self.TASKS, TaskQuery(limit=2, offset=10), NOW)
        assert len(page.items) == 0
        assert page.total == 5
        assert page.has_more is False


# ── TaskPage.has_more ────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=1, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(5)], total=5, limit=1, offset=4)
        assert page.has_more is False

